class Component extends DCLogic {
  route() { return window.AHV_CONFIRM_RENDER ? window.AHV_CONFIRM_RENDER.resolveRoute(this.props.route) : null; }
  componentDidMount() { const R = this.route(); if (R) { window.AHV_CONFIRM_RENDER.applyHead(R); this._head = R.path; } }
  componentDidUpdate() { const R = this.route(); if (R && R.path !== this._head) { window.AHV_CONFIRM_RENDER.applyHead(R); this._head = R.path; } }
  renderVals() {
    const P = window.AHV_CONFIRM_RENDER, D = window.AHV_CONFIRM || {}; const R = this.route();
    const guard = () => {}; /* preview-only nav guard neutralised for the published site */
    const receipt = P ? P.resolveReceipt(this.props.prototypeReceipt) : false;
    // Utility routes (/book-now/, /cart/, /checkout/) carry their own exact direct-visit copy and have no
    // receipt state at all: they are anonymous fallback states, never a confirmation of a transaction.
    const dv = (R && R.directVisit) || D.directVisit || { heading: '', body: '', link: { href: '', label: '' } };
    const utility = !!(R && R.utility);
    // A route that carries its own source images binds them here; every other route keeps the existing
    // default artwork untouched. Built as React nodes so no raw interpolated src is ever requested.
    const own = (R && R.images && R.images.length) ? R.images : null;
    // Route-specific breadcrumb from the record; routes without a recorded chain render no nav.
    const bcChain = (R && R.crumbs) || [];
    const bcVals = { showBreadcrumb: bcChain.length > 0,
      crumbs: bcChain.slice(0, -1).map(c => ({ url: 'https://ayurvedichealingvillage.com' + c.path, label: c.label })),
      crumbLast: bcChain.length ? bcChain[bcChain.length - 1].label : '' };
    const base = Object.assign({}, bcVals, { guard, dv, isDirect: utility || !receipt || !R, isNext: false, isLegacy: false, isImage: false,
      hasOwnImages: !!own, hasDefaultArtwork: !own,
      ownImagesEl: own ? own.map((im, k) => React.createElement('img', { key: 'oi' + k, src: im.file,
        alt: im.alt || '', width: im.width, height: im.height, loading: 'lazy',
        'data-source-pointer': im.ptr,
        // natural proportions, capped at the recorded natural width so the 83x56 logo is never upscaled
        style: { display: 'block', width: '100%', maxWidth: im.width + 'px', height: 'auto', borderRadius: '4px' } })) : null });
    if (!R || !receipt || utility) return base;
    // Own-source images belong to the route, not to a state: carry them into every branch below.
    const imgFields = { hasOwnImages: base.hasOwnImages, hasDefaultArtwork: base.hasDefaultArtwork,
      ownImagesEl: base.ownImagesEl };
    const A = P.A;
    const btn = (k) => k === 'primary'
      ? 'display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:0 26px;background:#5A4420;color:#F7F4EA;border-radius:4px;font-weight:700;font-size:16px'
      : 'display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:0 26px;background:#fff;color:#5A4420;border:2px solid #5A4420;border-radius:4px;font-weight:700;font-size:16px';
    const v = R.variant;
    const out = Object.assign(base, { isNext: v === 'next-steps', isLegacy: v === 'legacy-queue', isImage: v === 'image-receipt', h1: R.h1 });
    if (v === 'next-steps') {
      const em = R.h1Em; const lead = em ? R.h1.slice(0, R.h1.lastIndexOf(em)) : R.h1;
      Object.assign(out, {
        hero1024: R.hero === 'landscape1024', hero1440: R.hero === 'landscape1440', lotus: !!R.lotus,
        hasEyebrow: !!R.eyebrow, eyebrow: R.eyebrow, h1Lead: lead, hasEm: !!em, h1Em: em,
        lede: R.lede, hasNote: !!R.note, note: R.note, hasStepsHeading: !!R.stepsHeading, stepsHeading: R.stepsHeading,
        steps: R.steps.map(s => Object.assign({}, s, { when: s.when || false })),
        sooner: R.sooner, hasSoonerEyebrow: !!R.sooner.eyebrow,
        actions: R.sooner.actions.map(a => ({ href: a.href, label: a.label, rel: a.external ? 'noopener' : undefined, style: btn(a.kind) })),
        wait: R.wait, cards: R.wait.cards.map(c => Object.assign({}, c, { url: A + c.href, kicker: c.kicker || false, go: c.go || false })),
        hasTrust: !!R.trust, trust: R.trust ? { seal: R.trust.seal, items: R.trust.items.map(t => ({ b: t.b || false, rest: t.rest })) } : { seal: '', items: [] }
      });
    } else if (v === 'legacy-queue') {
      Object.assign(out, { brandLine: R.brandLine, paragraphs: R.paragraphs, action: R.action });
    } else {
      // Image receipt: the receipt image, optional source body paragraph and optional transcript are data-driven.
      // A route without them (the accepted /onlineconsultation-thanks/ dataset) renders exactly as before.
      // posterImage === false (a verified consultation receipt) renders the message as real text with no poster.
      const pi = R.posterImage === false ? null : (R.posterImage || D.images.poster);
      Object.assign(out, {
        transcript: R.transcript || { heading: '', lines: [] }, hasTranscript: !!R.transcript,
        hasPoster: !!pi, noPoster: !pi,
        poster: pi ? { src: pi.src, width: pi.width, height: pi.height, maxWidth: pi.width + 'px', ptr: pi.ptr || '' } : null,
        posterAlt: (pi && pi.alt) || '',
        // Built as a React node (same pattern as the Article Reader heroEl): a raw interpolated src attribute in the
        // template is prefetched by the browser before interpolation and 404s on the literal placeholder URL.
        posterEl: pi && React.createElement('img', { src: pi.src, alt: pi.alt || '', width: pi.width, height: pi.height,
          'data-source-pointer': pi.ptr || undefined,
          style: { width: '100%', maxWidth: pi.width + 'px', height: 'auto', display: 'block', borderRadius: '4px' } }),
        hasBody: !!(R.body && R.body.text), bodyText: (R.body && R.body.text) || '', bodyPtr: (R.body && R.body.ptr) || ''
      });
    }
    return out;
  }
}
